import XCTest
@testable import Remux

final class GhosttyTerminalSurfaceInteractionOutcomeTests: XCTestCase {
    func testFocusedTerminalInputSubmissionAcceptedStates() {
        XCTAssertTrue(FocusedTerminalInputSubmissionResult.accepted.isAccepted)
        XCTAssertTrue(FocusedTerminalInputSubmissionResult.empty.isAccepted)
        XCTAssertFalse(FocusedTerminalInputSubmissionResult.noFocusedSurface.isAccepted)
        XCTAssertFalse(FocusedTerminalInputSubmissionResult.transportUnavailable.isAccepted)
        XCTAssertFalse(FocusedTerminalInputSubmissionResult.surfaceRejected.isAccepted)
    }

    func testFocusedTerminalInputSubmissionDescriptions() {
        let cases: [(FocusedTerminalInputSubmissionResult, String)] = [
            (.accepted, "accepted"),
            (.empty, "empty"),
            (.noFocusedSurface, "noFocusedSurface"),
            (.transportUnavailable, "transportUnavailable"),
            (.surfaceRejected, "surfaceRejected"),
        ]

        for (result, description) in cases {
            XCTAssertEqual(result.description, description)
        }
    }

    func testMouseInputSubmissionSentState() {
        let missingTarget = UUID()

        XCTAssertTrue(GhosttyMouseInputSubmissionOutcome.sent.isSent)
        XCTAssertFalse(GhosttyMouseInputSubmissionOutcome.noFocusedSurface.isSent)
        XCTAssertFalse(GhosttyMouseInputSubmissionOutcome.missingTarget(missingTarget).isSent)
        XCTAssertFalse(GhosttyMouseInputSubmissionOutcome.transportUnavailable.isSent)
        XCTAssertFalse(GhosttyMouseInputSubmissionOutcome.surfaceRejected.isSent)
    }

}

import XCTest
@testable import Remux

final class SSHAuthResolverTests: XCTestCase {
    func testResolvesPasswordIdentityThroughIdentity() async throws {
        let identity = SSHIdentity(
            id: UUID(),
            name: "Work password",
            authenticationKind: .password
        )
        let server = SavedServer(
            displayName: "Server",
            host: "server.example.test",
            username: "deploy",
            identityID: identity.id
        )
        let resolver = SSHAuthResolver(credentialStore: TestSSHCredentialStore(credentials: [
            identity.id: .password("secret"),
        ]))

        let auth = try await resolver.resolve(
            server: server,
            in: ConnectionLibrarySnapshot(servers: [server], workspaces: [], identities: [identity])
        )

        XCTAssertEqual(auth.identityID, identity.id)
        XCTAssertEqual(auth.username, "deploy")
        XCTAssertEqual(auth.displayLabel, "Work password")
        XCTAssertEqual(auth.credential, .password("secret"))
    }

    func testMissingIdentityFailsExplicitly() async throws {
        let identityID = UUID()
        let server = SavedServer(
            displayName: "Server",
            host: "server.example.test",
            username: "deploy",
            identityID: identityID
        )
        let resolver = SSHAuthResolver(credentialStore: TestSSHCredentialStore())

        do {
            _ = try await resolver.resolve(
                server: server,
                in: ConnectionLibrarySnapshot(servers: [server], workspaces: [])
            )
            XCTFail("Expected missing identity error")
        } catch let error as SSHAuthResolverError {
            XCTAssertEqual(error, .missingIdentity(identityID))
        }
    }

    func testMissingCredentialFailsExplicitly() async throws {
        let identity = SSHIdentity(
            name: "Work password",
            authenticationKind: .password
        )
        let server = SavedServer(
            displayName: "Server",
            host: "server.example.test",
            username: "deploy",
            identityID: identity.id
        )
        let resolver = SSHAuthResolver(credentialStore: TestSSHCredentialStore())

        do {
            _ = try await resolver.resolve(
                server: server,
                in: ConnectionLibrarySnapshot(servers: [server], workspaces: [], identities: [identity])
            )
            XCTFail("Expected missing credential error")
        } catch let error as SSHAuthResolverError {
            XCTAssertEqual(error, .missingCredential(identity.id))
        }
    }

    func testCredentialKindMismatchFailsExplicitly() async throws {
        let identity = SSHIdentity(
            name: "Work key",
            authenticationKind: .privateKey
        )
        let server = SavedServer(
            displayName: "Server",
            host: "server.example.test",
            username: "deploy",
            identityID: identity.id
        )
        let resolver = SSHAuthResolver(credentialStore: TestSSHCredentialStore(credentials: [
            identity.id: .password("secret"),
        ]))

        do {
            _ = try await resolver.resolve(
                server: server,
                in: ConnectionLibrarySnapshot(servers: [server], workspaces: [], identities: [identity])
            )
            XCTFail("Expected credential kind mismatch error")
        } catch let error as SSHAuthResolverError {
            XCTAssertEqual(
                error,
                .credentialKindMismatch(
                    identityID: identity.id,
                    expected: .privateKey,
                    actual: .password
                )
            )
        }
    }

    func testResolvesPrivateKeyIdentityThroughIdentity() async throws {
        let identity = SSHIdentity(
            name: "Work key",
            authenticationKind: .privateKey,
            publicFingerprint: "SHA256:ut9xpxBjkrwDyq3o7dO0r/opPmzTsBSslfZtdaBGYWk"
        )
        let server = SavedServer(
            displayName: "Server",
            host: "server.example.test",
            username: "deploy",
            identityID: identity.id
        )
        let credential = SSHPrivateKeyCredential(privateKeyPEM: Self.ed25519Key, passphrase: "secret")
        let resolver = SSHAuthResolver(credentialStore: TestSSHCredentialStore(credentials: [
            identity.id: .privateKey(credential),
        ]))

        let auth = try await resolver.resolve(
            server: server,
            in: ConnectionLibrarySnapshot(servers: [server], workspaces: [], identities: [identity])
        )

        XCTAssertEqual(auth.identityID, identity.id)
        XCTAssertEqual(auth.username, "deploy")
        XCTAssertEqual(auth.displayLabel, "Work key")
        XCTAssertEqual(auth.credential, .privateKey(credential))
    }

    private static let ed25519Key = """
    [REDACTED]
    """
}

private actor TestSSHCredentialStore: SSHCredentialStore {
    private var credentials: [UUID: SSHCredential]

    init(credentials: [UUID: SSHCredential] = [:]) {
        self.credentials = credentials
    }

    func loadCredential(identityID: UUID) async throws -> SSHCredential? {
        credentials[identityID]
    }

    func saveCredential(_ credential: SSHCredential, identityID: UUID) async throws {
        credentials[identityID] = credential
    }

    func deleteCredential(identityID: UUID) async throws {
        credentials[identityID] = nil
    }
}

import Foundation
import GhosttyKit
import XCTest

@testable import Remux

@MainActor
final class TmuxScreenModelForegroundActiveCheckTests: XCTestCase {
    func testInitialConnectWaitsForMeasuredViewport() async throws {
        let target = makeTarget()
        let transport = ForegroundInactiveTransport(isActive: true)
        var transportFactoryCallCount = 0
        let model = TmuxScreenModel(
            target: target,
            sessionInstanceID: UUID(),
            transportFactory: { _ in
                transportFactoryCallCount += 1
                return transport
            },
            onRuntimeStateChange: { _ in }
        )
        defer {
            Task { @MainActor in
                await model.stop()
            }
        }

        XCTAssertEqual(transportFactoryCallCount, 1)
        try await Task.sleep(for: .milliseconds(80))
        let didStartBeforeViewport = await transport.didStart()
        XCTAssertFalse(didStartBeforeViewport)

        model.terminalScreenAdapter.prepareInitialViewport(
            size: CGSize(width: 420, height: 756),
            scale: 3
        )

        try await waitUntil("transport did not start after viewport report") {
            await transport.didStart()
        }
        let viewport = await transport.startedViewport()
        XCTAssertNotNil(viewport)
        XCTAssertNotEqual(viewport, .default)
        XCTAssertEqual(viewport?.pixelWidth, 1260)
        XCTAssertEqual(viewport?.pixelHeight, 2268)
        let measuredViewport = try XCTUnwrap(viewport)
        let measuredSize = TmuxSessionController.ClientSize(
            cols: UInt32(measuredViewport.columns),
            rows: UInt32(measuredViewport.rows)
        )
        XCTAssertEqual(model.carriedClientSize, measuredSize)
        XCTAssertFalse(
            model.submitClientSizeIfChanged(measuredSize),
            "the measured pre-connect grid must seed the screen-model authority"
        )
        await model.stop()
    }

    func testStopBeforeViewportClosesClaimedTransportExactlyOnce() async throws {
        let transport = ForegroundInactiveTransport(isActive: true)
        var transportFactoryCallCount = 0
        let model = TmuxScreenModel(
            target: makeTarget(),
            sessionInstanceID: UUID(),
            transportFactory: { _ in
                transportFactoryCallCount += 1
                return transport
            },
            onRuntimeStateChange: { _ in }
        )

        XCTAssertEqual(transportFactoryCallCount, 1)
        let didStart = await transport.didStart()
        XCTAssertFalse(didStart)

        await model.stop()
        await model.stop()

        let closeDispositions = await transport.closeDispositions()
        XCTAssertEqual(closeDispositions, [.reusable])
    }

    func testScreenModelRejectsRepeatedGridBeforeControllerSubmission() async throws {
        let transport = ForegroundInactiveTransport(isActive: true)
        let model = TmuxScreenModel(
            target: makeTarget(),
            sessionInstanceID: UUID(),
            transportFactory: { _ in transport },
            onRuntimeStateChange: { _ in },
            initialClientSize: Self.initialClientSize
        )
        defer {
            Task { @MainActor in
                await model.stop()
            }
        }

        try await waitUntil("transport did not start") {
            await transport.didStart()
        }
        XCTAssertEqual(model.carriedClientSize, Self.initialClientSize)
        XCTAssertFalse(model.submitClientSizeIfChanged(Self.initialClientSize))

        let changed = TmuxSessionController.ClientSize(cols: 52, rows: 31)
        XCTAssertTrue(model.submitClientSizeIfChanged(changed))
        XCTAssertEqual(model.carriedClientSize, changed)

        await model.stop()
    }

    func testForegroundInvalidatesInactiveTransportAndReportsForegroundDisconnect() async throws {
        let target = makeTarget()
        let instanceID = UUID()
        let transport = ForegroundInactiveTransport(isActive: false)
        var updates: [TerminalRuntimeStateUpdate] = []
        let model = TmuxScreenModel(
            target: target,
            sessionInstanceID: instanceID,
            transportFactory: { _ in transport },
            onRuntimeStateChange: { updates.append($0) },
            initialClientSize: Self.initialClientSize
        )
        defer {
            Task { @MainActor in
                await model.stop()
            }
        }

        try await waitUntil("transport did not start") {
            await transport.didStart()
        }
        model.session?.handleStateForTesting(.ready)
        updates.removeAll()

        model.handleAppLifecyclePhase(.active)

        try await waitUntil("inactive foreground transport was not invalidated") {
            await transport.closeDispositions().contains(.invalidated)
        }
        try await waitUntil("foreground disconnect was not reported") {
            updates.contains {
                $0.workspaceID == target.workspace.id
                    && $0.instanceID == instanceID
                    && $0.source == .foreground
                    && $0.state.disconnectedReason == GhosttyTerminalDisconnectReasonClassifier
                        .foregroundMissingHost()
            }
        }
        await model.stop()
    }

    func testForegroundDoesNotProbeTransportWhileSessionIsStillConnecting() async throws {
        let target = makeTarget()
        let transport = ForegroundInactiveTransport(isActive: false)
        var updates: [TerminalRuntimeStateUpdate] = []
        let model = TmuxScreenModel(
            target: target,
            sessionInstanceID: UUID(),
            transportFactory: { _ in transport },
            onRuntimeStateChange: { updates.append($0) },
            initialClientSize: Self.initialClientSize
        )
        defer {
            Task { @MainActor in
                await model.stop()
            }
        }

        try await waitUntil("transport did not start") {
            await transport.didStart()
        }
        try await waitUntil("session did not enter a connecting state") {
            guard let state = model.session?.state else { return false }
            switch state {
            case .attaching, .syncing:
                return true
            case .detached, .ready, .closed:
                return false
            }
        }
        updates.removeAll()

        model.handleAppLifecyclePhase(.active)
        try await Task.sleep(for: .milliseconds(80))

        let activeCheckCount = await transport.activeCheckCount()
        let closeDispositions = await transport.closeDispositions()
        XCTAssertEqual(activeCheckCount, 0)
        XCTAssertTrue(closeDispositions.isEmpty)
        XCTAssertTrue(updates.allSatisfy { $0.source != .foreground })
        await model.stop()
    }

    func testStaleForegroundProbeDoesNotInvalidateStoppedLink() async throws {
        let runtime = try GhosttyKitRuntime()
        let transport = ForegroundSuspendingTransport(isActiveAfterResume: false)
        let session = TmuxTerminalSession(
            app: runtime.appHandleForTesting,
            transport: transport,
            baseSurfaceConfig: { runtime.makeTmuxBaseSurfaceConfig() },
            paneViewTheme: { .remuxDark },
            createPaneSurface: { _, _, _, _, _, _, _, completion in
                completion(.failure(.surfaceCreationFailed(
                    GHOSTTY_TERMINAL_SURFACE_RESULT_INVALID_INPUT
                )))
            }
        )
        defer {
            Task { @MainActor in
                await session.shutdown()
            }
        }

        session.connect(viewport: .default)
        try await waitUntil("transport did not start") {
            await transport.didStart()
        }
        session.handleStateForTesting(.ready)

        var invalidatedReasons: [TerminalDisconnectReason] = []
        let probe = Task { @MainActor in
            await session.invalidateInactiveTransportOnForeground { reason in
                invalidatedReasons.append(reason)
            }
        }
        try await waitUntil("transport was not probed") {
            await transport.activeCheckCount() == 1
        }

        await session.disconnect()
        await transport.resumeActiveCheck()
        let reason = await probe.value
        let closeDispositions = await transport.closeDispositions()

        XCTAssertNil(reason)
        XCTAssertTrue(invalidatedReasons.isEmpty)
        XCTAssertEqual(closeDispositions, [.reusable])
    }

    private func waitUntil(
        _ failureMessage: String,
        timeout: Duration = .seconds(2),
        condition: () async -> Bool
    ) async throws {
        let clock = ContinuousClock()
        let deadline = clock.now.advanced(by: timeout)
        while clock.now < deadline {
            if await condition() {
                return
            }
            try await Task.sleep(for: .milliseconds(20))
        }
        XCTFail(failureMessage)
    }

    private func makeTarget() -> TmuxConnectionTarget {
        let server = SavedServer(
            displayName: "Build Host",
            host: "build.example.test",
            username: "builder"
        )
        let workspace = SavedWorkspace(serverID: server.id, sessionName: "base")
        return TmuxConnectionTarget(
            server: server,
            workspace: workspace,
            sshAuth: .password(
                username: server.username,
                password: "secret",
                identityID: server.identityID,
                displayLabel: server.displayName
            )
        )
    }

    private static let initialClientSize = TmuxSessionController.ClientSize(
        cols: 47,
        rows: 38
    )
}

private actor ForegroundInactiveTransport: TmuxControlTransport, TmuxControlTransportLivenessChecking {
    nonisolated let receivedBytes: AsyncThrowingStream<Data, Error>

    private let isActive: Bool
    private let continuation: AsyncThrowingStream<Data, Error>.Continuation
    private var started = false
    private var recordedInitialViewport: TmuxControlViewport?
    private var recordedActiveCheckCount = 0
    private var recordedCloseDispositions: [TmuxControlTransportCloseDisposition] = []

    init(isActive: Bool) {
        self.isActive = isActive

        var capturedContinuation: AsyncThrowingStream<Data, Error>.Continuation?
        receivedBytes = AsyncThrowingStream { continuation in
            capturedContinuation = continuation
        }
        continuation = capturedContinuation!
    }

    func start(initialViewport: TmuxControlViewport?) async throws {
        recordedInitialViewport = initialViewport
        started = true
    }

    func send(_ data: Data) async throws {
        _ = data
    }

    func close(disposition: TmuxControlTransportCloseDisposition) async {
        recordedCloseDispositions.append(disposition)
        continuation.finish()
    }

    func isControlChannelActive() async -> Bool {
        recordedActiveCheckCount += 1
        return isActive
    }

    func didStart() -> Bool {
        started
    }

    func startedViewport() -> TmuxControlViewport? {
        recordedInitialViewport
    }

    func closeDispositions() -> [TmuxControlTransportCloseDisposition] {
        recordedCloseDispositions
    }

    func activeCheckCount() -> Int {
        recordedActiveCheckCount
    }
}

private actor ForegroundSuspendingTransport: TmuxControlTransport, TmuxControlTransportLivenessChecking {
    nonisolated let receivedBytes: AsyncThrowingStream<Data, Error>

    private let isActiveAfterResume: Bool
    private let continuation: AsyncThrowingStream<Data, Error>.Continuation
    private var activeCheckContinuation: CheckedContinuation<Void, Never>?
    private var started = false
    private var recordedActiveCheckCount = 0
    private var recordedCloseDispositions: [TmuxControlTransportCloseDisposition] = []

    init(isActiveAfterResume: Bool) {
        self.isActiveAfterResume = isActiveAfterResume

        var capturedContinuation: AsyncThrowingStream<Data, Error>.Continuation?
        receivedBytes = AsyncThrowingStream { continuation in
            capturedContinuation = continuation
        }
        continuation = capturedContinuation!
    }

    func start(initialViewport: TmuxControlViewport?) async throws {
        _ = initialViewport
        started = true
    }

    func send(_ data: Data) async throws {
        _ = data
    }

    func close(disposition: TmuxControlTransportCloseDisposition) async {
        recordedCloseDispositions.append(disposition)
        continuation.finish()
    }

    func isControlChannelActive() async -> Bool {
        recordedActiveCheckCount += 1
        await withCheckedContinuation { continuation in
            activeCheckContinuation = continuation
        }
        return isActiveAfterResume
    }

    func resumeActiveCheck() {
        activeCheckContinuation?.resume()
        activeCheckContinuation = nil
    }

    func didStart() -> Bool {
        started
    }

    func closeDispositions() -> [TmuxControlTransportCloseDisposition] {
        recordedCloseDispositions
    }

    func activeCheckCount() -> Int {
        recordedActiveCheckCount
    }
}

import Foundation
import XCTest
@testable import Remux

final class RemuxPreparedTransportCacheTests: XCTestCase {
    func testClaimReusableTransportReturnsAndRemovesPreparedTransport() throws {
        var cache = RemuxPreparedTransportCache()
        let target = makeTarget()
        let transport = CacheTransport()

        XCTAssertNil(cache.store(PreparedTmuxControlTransport(target: target, transport: transport)))

        guard case .claimed(let prepared) = cache.claim(for: target) else {
            XCTFail("expected reusable prepared transport")
            return
        }
        XCTAssertEqual((prepared.transport as? CacheTransport)?.id, transport.id)
        guard case .missing = cache.claim(for: target) else {
            XCTFail("expected cache miss after claim")
            return
        }
    }

    func testClaimStaleTransportReturnsDiscardAndRemovesPreparedTransport() throws {
        var cache = RemuxPreparedTransportCache()
        let target = makeTarget(password: "old")
        let currentTarget = makeTarget(
            serverID: target.server.id,
            workspaceID: target.workspace.id,
            password: "new"
        )
        let transport = CacheTransport()

        XCTAssertNil(cache.store(PreparedTmuxControlTransport(target: target, transport: transport)))

        guard case .discardedStale(let prepared) = cache.claim(for: currentTarget) else {
            XCTFail("expected stale prepared transport discard")
            return
        }
        XCTAssertEqual((prepared.transport as? CacheTransport)?.id, transport.id)
        guard case .missing = cache.claim(for: currentTarget) else {
            XCTFail("expected cache miss after stale discard")
            return
        }
    }

    func testClaimAllowsSavedUsernameDriftWhenResolvedAuthMatches() throws {
        var cache = RemuxPreparedTransportCache()
        let target = makeTarget()
        let currentTarget = makeTarget(
            serverID: target.server.id,
            workspaceID: target.workspace.id,
            serverUsername: "renamed-user",
            sshAuth: target.sshAuth
        )
        let transport = CacheTransport()

        XCTAssertNil(cache.store(PreparedTmuxControlTransport(target: target, transport: transport)))

        guard case .claimed(let prepared) = cache.claim(for: currentTarget) else {
            XCTFail("expected reusable prepared transport")
            return
        }
        XCTAssertEqual((prepared.transport as? CacheTransport)?.id, transport.id)
    }

    func testClaimRejectsResolvedAuthUsernameDrift() throws {
        var cache = RemuxPreparedTransportCache()
        let target = makeTarget()
        let currentTarget = makeTarget(
            serverID: target.server.id,
            workspaceID: target.workspace.id,
            sshAuth: .password(
                username: "other-user",
                password: "secret",
                identityID: target.server.identityID,
                displayLabel: target.server.displayName
            )
        )
        let transport = CacheTransport()

        XCTAssertNil(cache.store(PreparedTmuxControlTransport(target: target, transport: transport)))

        guard case .discardedStale(let prepared) = cache.claim(for: currentTarget) else {
            XCTFail("expected stale prepared transport discard")
            return
        }
        XCTAssertEqual((prepared.transport as? CacheTransport)?.id, transport.id)
    }

    func testStoreReplacementReturnsPreviousTransport() throws {
        var cache = RemuxPreparedTransportCache()
        let target = makeTarget()
        let firstTransport = CacheTransport()
        let secondTransport = CacheTransport()

        XCTAssertNil(cache.store(PreparedTmuxControlTransport(target: target, transport: firstTransport)))
        let replaced = try XCTUnwrap(
            cache.store(PreparedTmuxControlTransport(target: target, transport: secondTransport))
        )
        XCTAssertEqual((replaced.transport as? CacheTransport)?.id, firstTransport.id)

        guard case .claimed(let prepared) = cache.claim(for: target) else {
            XCTFail("expected replacement transport")
            return
        }
        XCTAssertEqual((prepared.transport as? CacheTransport)?.id, secondTransport.id)
    }

    func testRemoveByServerExcludesSelectedWorkspace() throws {
        var cache = RemuxPreparedTransportCache()
        let serverID = SavedServer.ID()
        let removedTarget = makeTarget(serverID: serverID, workspaceID: SavedWorkspace.ID())
        let retainedTarget = makeTarget(serverID: serverID, workspaceID: SavedWorkspace.ID())
        let otherServerTarget = makeTarget()
        let removedTransport = CacheTransport()
        let retainedTransport = CacheTransport()
        let otherServerTransport = CacheTransport()

        XCTAssertNil(cache.store(PreparedTmuxControlTransport(target: removedTarget, transport: removedTransport)))
        XCTAssertNil(cache.store(PreparedTmuxControlTransport(target: retainedTarget, transport: retainedTransport)))
        XCTAssertNil(cache.store(PreparedTmuxControlTransport(target: otherServerTarget, transport: otherServerTransport)))

        let removed = cache.remove(
            serverID: serverID,
            excludingWorkspaceID: retainedTarget.workspace.id
        )
        XCTAssertEqual(removed.count, 1)
        XCTAssertEqual((removed.first?.transport as? CacheTransport)?.id, removedTransport.id)

        guard case .claimed(let retained) = cache.claim(for: retainedTarget) else {
            XCTFail("expected excluded workspace to remain cached")
            return
        }
        XCTAssertEqual((retained.transport as? CacheTransport)?.id, retainedTransport.id)
        guard case .claimed(let otherServer) = cache.claim(for: otherServerTarget) else {
            XCTFail("expected other server workspace to remain cached")
            return
        }
        XCTAssertEqual((otherServer.transport as? CacheTransport)?.id, otherServerTransport.id)
    }

    func testDrainReturnsAllPreparedTransportsAndEmptiesCache() throws {
        var cache = RemuxPreparedTransportCache()
        let firstTarget = makeTarget()
        let secondTarget = makeTarget()
        let firstTransport = CacheTransport()
        let secondTransport = CacheTransport()

        XCTAssertNil(cache.store(PreparedTmuxControlTransport(target: firstTarget, transport: firstTransport)))
        XCTAssertNil(cache.store(PreparedTmuxControlTransport(target: secondTarget, transport: secondTransport)))

        let drainedIDs = Set(cache.drain().compactMap { ($0.transport as? CacheTransport)?.id })
        XCTAssertEqual(drainedIDs, Set([firstTransport.id, secondTransport.id]))
        guard case .missing = cache.claim(for: firstTarget) else {
            XCTFail("expected cache miss after drain")
            return
        }
        guard case .missing = cache.claim(for: secondTarget) else {
            XCTFail("expected cache miss after drain")
            return
        }
    }
}

private func makeTarget(
    serverID: SavedServer.ID = SavedServer.ID(),
    workspaceID: SavedWorkspace.ID = SavedWorkspace.ID(),
    serverUsername: String = "builder",
    password: String = "secret",
    sshAuth: ResolvedSSHAuth? = nil,
    terminalSettings: TerminalSettings = .default
) -> TmuxConnectionTarget {
    let server = SavedServer(
        id: serverID,
        displayName: "Build Host",
        host: "build.example.test",
        username: serverUsername
    )
    let workspace = SavedWorkspace(
        id: workspaceID,
        serverID: serverID,
        sessionName: "base",
        lastOpenedAt: Date(timeIntervalSince1970: 0)
    )
    return TmuxConnectionTarget(
        server: server,
        workspace: workspace,
        sshAuth: sshAuth ?? .password(
            username: server.username,
            password: password,
            identityID: server.identityID,
            displayLabel: server.displayName
        ),
        terminalSettings: terminalSettings
    )
}

private final class CacheTransport: @unchecked Sendable, TmuxControlTransport {
    let id = UUID()
    let receivedBytes: AsyncThrowingStream<Data, Error> = AsyncThrowingStream { continuation in
        continuation.finish()
    }

    func prepare() async {}

    func start(initialViewport: TmuxControlViewport?) async throws {
        _ = initialViewport
    }

    func send(_ data: Data) async throws {
        _ = data
    }

    func close(disposition: TmuxControlTransportCloseDisposition) async {
        _ = disposition
    }
}

# Remux Site

The production website for Remux, served at `getremux.app`.

## Product story

The site follows five sections: home, workspace, preview, controls, and get. It introduces Remux as
an iPhone interface for tmux, then shows how people navigate sessions, preview terminal links, use
terminal controls that a phone keyboard omits, and join the public beta.

## Design constraints

- use tmux and terminal UI as a quiet layout grammar, not decoration;
- use the production app icon and its green-black, soft-teal, and live-amber palette;
- use proportional type for product messaging and monospace for labels, controls, and status;
- cap the desktop content frame at 1320 pixels, with a media-led 42/58 feature split;
- size headings from their copy container so reversed layouts retain the same hierarchy;
- cap desktop feature content at 720 pixels high and leave clear space around the full device;
- use 24-pixel gutters between desktop sections and 16-pixel gutters between mobile sections;
- use the same copy inset for hero and feature panes while preserving their type hierarchy;
- keep feature detail to three compact, concrete rows with no numbering or card treatment;
- let sections scroll naturally on mobile instead of shrinking an entire section into one viewport;
- show one dominant visual or interaction per section and avoid nested decorative chrome;
- keep view switching in the section bar instead of nesting a second tab bar inside the media pane;
- preserve device geometry and size phones from the media pane height, not from viewport width;
- use the official iPhone Air frame for the document Preview composition;
- let the current product walkthrough fill the home media pane, with a still for reduced motion;
- keep the desktop tmux status line as secondary navigation and make it non-fixed on mobile;
- point TestFlight actions to the public invite at <https://testflight.apple.com/join/fHqG1ruE>.

